// Regenerates the third-party libraries the plugin runtime ships in
// `Sources/GraphiteUI/Resources/CommunityPluginRuntime/Vendor/`, from the exact versions
// pinned in this folder's package.json (`npm ci` first). Obsidian gives plugins these
// libraries, so plugins expect them: moment (`moment`), js-yaml (`parseYaml`), Lucide
// (`setIcon`), and CodeMirror 6 with Lezer (`require('@codemirror/…')`).
//
// Usage: node tools/build-vendored-libraries.js
'use strict';

const fileSystem = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');

const vendorFolder = path.resolve(__dirname, '../../../Sources/GraphiteUI/Resources/CommunityPluginRuntime/Vendor');
const licensesFolder = path.join(vendorFolder, 'Licenses');
const modulesFolder = path.resolve(__dirname, '../node_modules');

/// The CodeMirror and Lezer modules Obsidian provides to plugins through `require`.
const codeMirrorModuleNames = [
    '@codemirror/autocomplete', '@codemirror/commands', '@codemirror/language', '@codemirror/lint', '@codemirror/search',
    '@codemirror/state', '@codemirror/view', '@lezer/common', '@lezer/highlight', '@lezer/lr',
];

function withoutSourceMapReference(source) {
    return source.replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n');
}

function copyLibrary(packageName, relativeScriptPath, vendoredName) {
    const source = fileSystem.readFileSync(path.join(modulesFolder, packageName, relativeScriptPath), 'utf8');
    fileSystem.writeFileSync(path.join(vendorFolder, vendoredName), withoutSourceMapReference(source));
}

function packageVersion(packageName) {
    return JSON.parse(fileSystem.readFileSync(path.join(modulesFolder, packageName, 'package.json'), 'utf8')).version;
}

function copyLicense(packageName) {
    const packageFolder = path.join(modulesFolder, packageName);
    const licenseName = fileSystem.readdirSync(packageFolder).find((name) => /^licen[cs]e/i.test(name));
    if (!licenseName) throw new Error(packageName + ' has no license file.');
    fileSystem.writeFileSync(path.join(licensesFolder, packageName.replace('/', '__') + '.txt'), fileSystem.readFileSync(path.join(packageFolder, licenseName)));
}

async function buildCodeMirrorBundle() {
    const entrySource = [
        '// One copy of each module, so every plugin shares CodeMirror\'s classes, as in Obsidian.',
        'globalThis.GraphiteCodeMirrorModules = {',
        ...codeMirrorModuleNames.map((moduleName) => '    ' + JSON.stringify(moduleName) + ': require(' + JSON.stringify(moduleName) + '),'),
        '};',
    ].join('\n');
    const result = await esbuild.build({
        stdin: { contents: entrySource, resolveDir: path.resolve(__dirname, '..'), sourcefile: 'graphite-codemirror-modules.js' },
        bundle: true,
        format: 'iife',
        minify: true,
        target: 'safari17',
        legalComments: 'none',
        write: false,
    });
    const header = '/* CodeMirror 6 and Lezer for Obsidian plugins, bundled by Tests/CommunityPluginRuntimeTests/tools/build-vendored-libraries.js: '
        + codeMirrorModuleNames.map((moduleName) => moduleName + ' ' + packageVersion(moduleName)).join(', ') + '. MIT licensed; see Licenses/. */\n';
    fileSystem.writeFileSync(path.join(vendorFolder, 'codemirror-modules.min.js'), header + result.outputFiles[0].text);
}

async function main() {
    fileSystem.mkdirSync(licensesFolder, { recursive: true });
    copyLibrary('moment', 'min/moment.min.js', 'moment.min.js');
    copyLibrary('js-yaml', 'dist/js-yaml.min.js', 'js-yaml.min.js');
    copyLibrary('lucide', 'dist/umd/lucide.min.js', 'lucide.min.js');
    await buildCodeMirrorBundle();
    const licensedPackages = ['moment', 'js-yaml', 'lucide', ...codeMirrorModuleNames, 'style-mod', 'w3c-keyname', 'crelt'];
    for (const packageName of licensedPackages) copyLicense(packageName);
    const versions = licensedPackages.map((packageName) => '- `' + packageName + '` ' + packageVersion(packageName));
    fileSystem.writeFileSync(path.join(vendorFolder, 'VERSIONS.md'), [
        '# Vendored libraries of the plugin runtime',
        '',
        'Generated by `npm run build-vendored-libraries` in `Tests/CommunityPluginRuntimeTests` from the versions its package.json pins. Do not edit these files by hand. Each license is in `Licenses/`.',
        '',
        ...versions,
        '',
    ].join('\n'));
}

main().catch((error) => {
    console.error(error);
    process.exit(1);
});
